/**
 * Allows to register the Standard Diagram View diagram in the application.
 *
 * @author arichard
 */
@Service
public class SDVDescriptionProvider implements IViewDescriptionProvider {

    /**
     * We can't change this Id to "StandardDiagramView" because it would change all Diagram, Nodes and Edges
     * Descriptions Ids.
     */
    @Override
    public String getViewId() {
        return "GeneralViewDiagram";
    }

    @Override
    public IRepresentationDescriptionProvider getRepresentationDescriptionProvider() {
        return new SDVDiagramDescriptionProvider();
    }

    @Override
    public Optional<ColorPalette> buildColorPalette() {
        ColorPalette colorPalette = new ColorPaletteBuilder().colors(new ViewBuilders().newFixedColor()
                        .name(AddYourFirstElement.COLOR_NAME)
                        .value("url(" + AddYourFirstElement.BASE64 + ") no-repeat center center / contain")
                        .build(),
                        new ViewBuilders().newFixedColor()
                                .name("actionGreen")
                                .value("#466044")
                                .build())
                .build();
        return Optional.of(colorPalette);
    }
}
